CREATE TABLE public.learning_spaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, invite_code uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_spaces TO authenticated;
GRANT ALL ON public.learning_spaces TO service_role;
ALTER TABLE public.learning_spaces ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.learning_members (user_id uuid PRIMARY KEY, space_id uuid NOT NULL REFERENCES public.learning_spaces(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.learning_members TO authenticated;
GRANT ALL ON public.learning_members TO service_role;
ALTER TABLE public.learning_members ENABLE ROW LEVEL SECURITY;
CREATE INDEX learning_members_space ON public.learning_members(space_id);
CREATE FUNCTION public.in_learning_space(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.learning_members WHERE space_id = target AND user_id = auth.uid()); $$;
REVOKE ALL ON FUNCTION public.in_learning_space(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.in_learning_space(uuid) TO authenticated;
CREATE POLICY member_space_read ON public.learning_spaces FOR SELECT TO authenticated USING(public.in_learning_space(id));
CREATE POLICY members_read ON public.learning_members FOR SELECT TO authenticated USING(public.in_learning_space(space_id));
CREATE TABLE public.lesson_results (user_id uuid NOT NULL, lesson_id text NOT NULL, xp integer NOT NULL CHECK(xp BETWEEN 0 AND 100), correct integer NOT NULL CHECK(correct BETWEEN 0 AND 20), completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,lesson_id));
GRANT SELECT ON public.lesson_results TO authenticated;
GRANT ALL ON public.lesson_results TO service_role;
ALTER TABLE public.lesson_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY results_read ON public.lesson_results FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.learning_members m WHERE m.user_id=lesson_results.user_id AND public.in_learning_space(m.space_id)));
CREATE TABLE public.learning_preferences (user_id uuid PRIMARY KEY, style text NOT NULL CHECK(style IN ('planner','connector','explorer')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.learning_preferences TO authenticated;
GRANT ALL ON public.learning_preferences TO service_role;
ALTER TABLE public.learning_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_read ON public.learning_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY preferences_insert ON public.learning_preferences FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY preferences_update ON public.learning_preferences FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.ensure_learning_space() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT space_id INTO sid FROM public.learning_members WHERE user_id=auth.uid(); IF sid IS NOT NULL THEN RETURN sid; END IF; INSERT INTO public.learning_spaces(owner_id) VALUES(auth.uid()) RETURNING id INTO sid; INSERT INTO public.learning_members(user_id,space_id) VALUES(auth.uid(),sid); RETURN sid; END; $$;
REVOKE ALL ON FUNCTION public.ensure_learning_space() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.ensure_learning_space() TO authenticated;
CREATE FUNCTION public.join_learning_space(code uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; current_space uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT id INTO target FROM public.learning_spaces WHERE invite_code=code FOR UPDATE; IF target IS NULL THEN RAISE EXCEPTION 'This invitation is no longer valid'; END IF; SELECT space_id INTO current_space FROM public.learning_members WHERE user_id=auth.uid(); IF current_space=target THEN RETURN target; END IF; IF (SELECT count(*) FROM public.learning_members WHERE space_id=target)>=2 THEN RAISE EXCEPTION 'This space already has two partners'; END IF; IF current_space IS NOT NULL THEN PERFORM 1 FROM public.learning_spaces WHERE id=current_space FOR UPDATE; IF (SELECT count(*) FROM public.learning_members WHERE space_id=current_space)>1 THEN RAISE EXCEPTION 'You already share a space with a partner'; END IF; DELETE FROM public.learning_members WHERE user_id=auth.uid(); END IF; INSERT INTO public.learning_members(user_id,space_id) VALUES(auth.uid(),target); RETURN target; END; $$;
REVOKE ALL ON FUNCTION public.join_learning_space(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.join_learning_space(uuid) TO authenticated;
CREATE FUNCTION public.rotate_learning_invite() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code uuid; BEGIN UPDATE public.learning_spaces SET invite_code=gen_random_uuid() WHERE owner_id=auth.uid() AND public.in_learning_space(id) RETURNING invite_code INTO code; IF code IS NULL THEN RAISE EXCEPTION 'Only the space creator can replace the invitation'; END IF; RETURN code; END; $$;
REVOKE ALL ON FUNCTION public.rotate_learning_invite() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.rotate_learning_invite() TO authenticated;